import type { Question } from '../../lib/types'

export const route53_cloudfront_questions: Question[] = [
  { id: 'd2-r53-001', domain: 2, topics: ['Route 53', 'routing policy', 'failover'], type: 'single', stem: 'An application is deployed in us-east-1 (primary) and eu-west-1 (standby). Traffic should go to eu-west-1 only when the primary fails health checks. Which Route 53 routing policy should be used?', options: [{ id: 'A', text: 'Weighted routing (50/50)' }, { id: 'B', text: 'Failover routing — routes to primary; fails over to secondary when primary health check fails' }, { id: 'C', text: 'Latency-based routing' }, { id: 'D', text: 'Geolocation routing' }], correct: ['B'], explanation: 'Route 53 failover routing has Active-Passive configuration: all traffic goes to the primary record. If the primary health check fails, Route 53 routes to the secondary. Requires health checks on both records.', distractors: { A: 'Weighted routing splits traffic by ratio — doesn\'t automatically failover based on health.', C: 'Latency routing sends users to the lowest-latency region — not specifically a failover mechanism.', D: 'Geolocation routing routes based on user geography — not based on health checks.' } },
  { id: 'd2-r53-002', domain: 2, topics: ['Route 53', 'alias record', 'CNAME'], type: 'single', stem: 'A company hosts a website at the zone apex (example.com — not www.example.com) and needs to point it to an Application Load Balancer. What type of record should be used?', options: [{ id: 'A', text: 'CNAME record — points to the ALB DNS name' }, { id: 'B', text: 'A record with the ALB IP address' }, { id: 'C', text: 'Route 53 Alias record — supports zone apex and targets AWS resources' }, { id: 'D', text: 'MX record' }], correct: ['C'], explanation: 'DNS CNAME records cannot be created at the zone apex (naked domain). Route 53 Alias records solve this — they can point to AWS resources (ALB, CloudFront, S3) at the apex. Alias records are free (no charge per query to AWS targets).', distractors: { A: 'A CNAME at the zone apex violates DNS standards and causes resolution issues.', B: 'ALB IP addresses change — hardcoding IPs would break when AWS changes them.', D: 'MX records are for email routing — not web traffic.' } },
  { id: 'd2-r53-003', domain: 2, topics: ['Route 53', 'health check', 'string matching'], type: 'single', stem: 'Route 53 should health check an application endpoint and mark it unhealthy if the response contains the string "ERROR". What health check configuration enables this?', options: [{ id: 'A', text: 'HTTP health check monitoring the response code only' }, { id: 'B', text: 'HTTP health check with string matching — Route 53 checks the first 5,120 bytes for the specified string' }, { id: 'C', text: 'CloudWatch alarm-based health check' }, { id: 'D', text: 'TCP health check' }], correct: ['B'], explanation: 'Route 53 HTTP/HTTPS health checks support string matching. The health check fails if the specified string is (or is not) found in the first 5,120 bytes of the response body.', distractors: { A: 'HTTP code-only health checks can\'t detect application-level errors that return 200 OK with "ERROR" in the body.', C: 'CloudWatch alarm health checks trigger based on metric alarms — not response body content.', D: 'TCP health checks only verify TCP connectivity — not HTTP response content.' } },
  { id: 'd2-r53-004', domain: 2, topics: ['Route 53', 'weighted routing', 'blue-green'], type: 'single', stem: 'A team is deploying a new version of their application. They want to gradually shift 10% of traffic to the new version while keeping 90% on the old version. Which Route 53 routing policy enables this?', options: [{ id: 'A', text: 'Failover routing' }, { id: 'B', text: 'Weighted routing — assign weights (e.g., 90 and 10) to different records' }, { id: 'C', text: 'Latency routing' }, { id: 'D', text: 'Multivalue answer routing' }], correct: ['B'], explanation: 'Weighted routing distributes traffic proportionally based on weights. Setting old=90, new=10 sends 10% to the new version. Gradually increase the new weight as confidence grows. Weights are relative values (not percentages), but the ratio determines distribution.', distractors: { A: 'Failover routing is active-passive based on health — not proportional traffic distribution.', C: 'Latency routing routes to the lowest-latency endpoint — not proportional.', D: 'Multivalue answer returns multiple IP addresses for simple load balancing — not proportional weighting.' } },
  { id: 'd2-r53-005', domain: 2, topics: ['CloudFront', 'distribution', 'cache behavior'], type: 'single', stem: 'A CloudFront distribution serves both static assets (/images/*, /css/*) and an API (/api/*). The API must never be cached. Static assets should cache for 24 hours. How is this configured?', options: [{ id: 'A', text: 'Set a single cache policy to 0 seconds for all paths' }, { id: 'B', text: 'Create multiple cache behaviors — /api/* with TTL=0, /images/* and /css/* with TTL=86400' }, { id: 'C', text: 'Disable CloudFront caching entirely' }, { id: 'D', text: 'Use Lambda@Edge to set cache headers per request' }], correct: ['B'], explanation: 'CloudFront supports multiple cache behaviors per distribution. Each behavior has its own cache policy, origin, and TTL settings based on URL path patterns. The default behavior (*) catches unmatched paths.', distractors: { A: 'A single 0-TTL policy would forward all requests to the origin — losing the caching benefit for static assets.', C: 'Disabling caching entirely defeats the purpose of CloudFront for static content.', D: 'Lambda@Edge works but is more complex — cache behaviors natively handle this without code.' } },
  { id: 'd2-r53-006', domain: 2, topics: ['CloudFront', 'OAC', 'S3 origin'], type: 'single', stem: 'A CloudFront distribution serves files from a private S3 bucket. The S3 bucket should not be publicly accessible — only CloudFront should be able to retrieve files. What should be configured?', options: [{ id: 'A', text: 'Make the S3 bucket public but restrict with IP-based bucket policy' }, { id: 'B', text: 'Use Origin Access Control (OAC) — CloudFront signs requests to S3; S3 bucket policy allows only the CloudFront distribution' }, { id: 'C', text: 'Use S3 Transfer Acceleration' }, { id: 'D', text: 'Store files in a public S3 bucket and use CloudFront WAF to block direct S3 access' }], correct: ['B'], explanation: 'OAC (the modern replacement for OAI) allows CloudFront to sign requests to S3 using SigV4. The S3 bucket policy grants access only to the CloudFront distribution\'s OAC identity. The bucket remains private — no public access needed.', distractors: { A: 'IP-based bucket policies are fragile because CloudFront\'s IPs change constantly.', C: 'S3 Transfer Acceleration speeds up direct uploads — not related to CloudFront origin access control.', D: 'WAF can\'t block direct S3 access — S3 bucket policies control access. Making S3 public is the wrong approach.' } },
  { id: 'd2-r53-007', domain: 2, topics: ['Route 53', 'geolocation routing'], type: 'single', stem: 'A company wants to serve a GDPR-compliant EU version of their website to all European users and a default version to everyone else. Which routing policy handles this?', options: [{ id: 'A', text: 'Latency-based routing' }, { id: 'B', text: 'Geolocation routing — route based on user\'s geographic location (continent, country, or US state)' }, { id: 'C', text: 'Weighted routing' }, { id: 'D', text: 'IP-based routing' }], correct: ['B'], explanation: 'Route 53 geolocation routing matches requests by user location. Create records for EU locations routing to the GDPR endpoint, and a default record (catches all unmatched locations) for everyone else.', distractors: { A: 'Latency routing optimizes for speed — doesn\'t route based on geographic compliance requirements.', C: 'Weighted routing splits traffic proportionally — not by geography.', D: 'IP-based routing uses IP prefix mappings — geolocation routing uses Route 53\'s built-in location data.' } },
  { id: 'd2-r53-008', domain: 2, topics: ['CloudFront', 'SSL', 'ACM'], type: 'single', stem: 'A company needs HTTPS on their CloudFront distribution using a custom domain (www.example.com). Which certificate service and region must be used?', options: [{ id: 'A', text: 'ACM certificate in the same region as the origin' }, { id: 'B', text: 'ACM certificate in us-east-1 (N. Virginia) — CloudFront only uses ACM certificates from us-east-1' }, { id: 'C', text: 'IAM server certificate in any region' }, { id: 'D', text: 'Self-signed certificate imported to ACM in any region' }], correct: ['B'], explanation: 'CloudFront requires ACM certificates to be in us-east-1 (N. Virginia), regardless of where the origin is. This is a critical exam trap. The certificate covers the CloudFront distribution\'s custom domain.', distractors: { A: 'Origin region is irrelevant for CloudFront certificate selection — always us-east-1.', C: 'IAM server certificates are legacy — ACM is recommended. But even with IAM certs, CloudFront can use them.', D: 'Self-signed certificates can be imported but the region requirement (us-east-1) still applies.' } },
  { id: 'd2-r53-009', domain: 2, topics: ['Route 53', 'private hosted zone'], type: 'single', stem: 'An application in a VPC needs to use internal DNS names (app.internal.example.com) that resolve only within the VPC. How is this configured?', options: [{ id: 'A', text: 'Public hosted zone with restricted access' }, { id: 'B', text: 'Route 53 Private Hosted Zone associated with the VPC — DNS names resolve only within the VPC' }, { id: 'C', text: 'EC2 instance running a BIND DNS server' }, { id: 'D', text: 'VPC DHCP options with custom DNS servers' }], correct: ['B'], explanation: 'Route 53 Private Hosted Zones provide DNS resolution only within associated VPCs. Resources outside the VPC cannot resolve these names. Multiple VPCs can be associated with the same private hosted zone for shared DNS.', distractors: { A: 'Public hosted zones are externally resolvable — security groups can\'t restrict DNS resolution.', C: 'EC2-based DNS requires managing servers — Route 53 private hosted zones are fully managed.', D: 'DHCP options can point to custom DNS — but Route 53 private hosted zones are the AWS-native solution.' } },
  { id: 'd2-r53-010', domain: 2, topics: ['CloudFront', 'Lambda@Edge', 'viewer request'], type: 'single', stem: 'A CloudFront distribution needs to inspect JWT tokens in request headers and block unauthorized requests before they reach the origin. Where should the Lambda@Edge function run?', options: [{ id: 'A', text: 'Origin request — runs before forwarding to origin' }, { id: 'B', text: 'Viewer request — runs at the edge for every request before checking the cache' }, { id: 'C', text: 'Viewer response — runs after the response is returned' }, { id: 'D', text: 'Origin response — runs after the origin returns a response' }], correct: ['B'], explanation: 'Viewer request Lambda@Edge runs for every request at the CloudFront edge, before cache check. This is the correct place for auth — block unauthorized requests before they hit the cache or origin.', distractors: { A: 'Origin request runs only for cache misses — a cached response bypasses origin request Lambda, so unauthorized users could get cached content.', C: 'Viewer response runs after content is returned — too late to block unauthorized requests.', D: 'Origin response runs after origin responds — unauthorized requests have already reached the origin.' } },
  { id: 'd2-r53-011', domain: 2, topics: ['Route 53', 'DNSSEC'], type: 'single', stem: 'A company wants to protect their Route 53 hosted zone from DNS spoofing attacks by enabling cryptographic signing of DNS records. What feature enables this?', options: [{ id: 'A', text: 'Route 53 health checks' }, { id: 'B', text: 'Route 53 DNSSEC signing — signs DNS records to prevent DNS cache poisoning and spoofing' }, { id: 'C', text: 'AWS Shield' }, { id: 'D', text: 'Route 53 Resolver DNSSEC validation' }], correct: ['B'], explanation: 'Route 53 DNSSEC signing enables cryptographic signing of all records in a hosted zone. DNS resolvers that support DNSSEC can validate the signatures, preventing cache poisoning and DNS hijacking attacks.', distractors: { A: 'Health checks monitor endpoint availability — not DNS security.', C: 'AWS Shield protects against DDoS attacks — not DNS spoofing.', D: 'Resolver DNSSEC validation validates responses from other DNS servers — it doesn\'t sign your own zone.' } },
  { id: 'd2-r53-012', domain: 2, topics: ['CloudFront', 'price class', 'cost'], type: 'single', stem: 'A company wants to reduce CloudFront costs by only serving content from edge locations in North America and Europe. What feature enables this?', options: [{ id: 'A', text: 'CloudFront geo restriction' }, { id: 'B', text: 'CloudFront price class — choose which edge location regions to use (Price Class 100 = US/Europe only)' }, { id: 'C', text: 'Route 53 geolocation routing' }, { id: 'D', text: 'CloudFront origin failover' }], correct: ['B'], explanation: 'CloudFront price classes control which edge locations serve the distribution. Price Class 100 (cheapest) uses only North America and Europe. Price Class 200 adds more regions. All uses all regions globally (most expensive but best performance).', distractors: { A: 'Geo restriction blocks specific countries from accessing content — doesn\'t select which edge locations to use.', C: 'Route 53 geolocation routes DNS — doesn\'t affect CloudFront edge location selection.', D: 'Origin failover provides HA for origins — not edge location selection.' } },
  { id: 'd2-r53-013', domain: 2, topics: ['Route 53', 'resolver', 'hybrid DNS'], type: 'single', stem: 'A company has on-premises DNS servers for internal hostnames (corp.example.com). EC2 instances in a VPC need to resolve these on-premises names. What should be configured?', options: [{ id: 'A', text: 'Create Route 53 public hosted zones for corp.example.com' }, { id: 'B', text: 'Route 53 Resolver outbound endpoint — forwards DNS queries for corp.example.com to on-premises DNS servers' }, { id: 'C', text: 'Set VPC DHCP options to point to on-premises DNS for all lookups' }, { id: 'D', text: 'Install custom DNS software on EC2 instances' }], correct: ['B'], explanation: 'Route 53 Resolver outbound endpoints forward specific DNS queries (by domain name) to on-premises DNS servers over Direct Connect or VPN. This enables hybrid DNS resolution without routing all DNS through on-premises.', distractors: { A: 'Public hosted zones are internet-facing — not for private on-premises hostnames.', C: 'Pointing all DNS to on-premises breaks AWS service resolution (S3, RDS, etc.) and adds a dependency.', D: 'Custom DNS software requires server management — Route 53 Resolver is managed.' } },
  { id: 'd2-r53-014', domain: 2, topics: ['CloudFront', 'WAF', 'security'], type: 'single', stem: 'A company wants to protect their CloudFront distribution with AWS WAF to block SQL injection attempts. In which region must the WAF Web ACL be created?', options: [{ id: 'A', text: 'Same region as the origin' }, { id: 'B', text: 'us-east-1 (N. Virginia) — CloudFront WAF Web ACLs must be in us-east-1' }, { id: 'C', text: 'Any region — WAF is global' }, { id: 'D', text: 'Same region as the CloudFront distribution' }], correct: ['B'], explanation: 'CloudFront WAF Web ACLs must be created in the US East (N. Virginia) region. This is the same restriction as CloudFront ACM certificates. Regional WAF Web ACLs (for ALB, API Gateway, etc.) can be in any region.', distractors: { A: 'Origin region is irrelevant — CloudFront WAF must be in us-east-1.', C: 'WAF is not global — Regional WAF is region-specific, and CloudFront WAF must be in us-east-1.', D: 'CloudFront distributions don\'t have a region — they\'re global, but associated WAF must be in us-east-1.' } },
  { id: 'd2-r53-015', domain: 2, topics: ['Route 53', 'latency routing'], type: 'single', stem: 'An application is deployed in us-east-1, eu-west-1, and ap-southeast-1. Users should be automatically routed to the region with the lowest network latency from their location. Which routing policy handles this?', options: [{ id: 'A', text: 'Geolocation routing' }, { id: 'B', text: 'Latency-based routing — Route 53 routes to the region with the lowest latency for the user' }, { id: 'C', text: 'Geoproximity routing' }, { id: 'D', text: 'Weighted routing with equal weights' }], correct: ['B'], explanation: 'Route 53 latency-based routing uses AWS\'s global network latency measurements to route users to the lowest-latency region. Route 53 knows approximate latency from different client locations to each AWS region.', distractors: { A: 'Geolocation routing routes by user\'s country/continent — may not map to lowest latency.', C: 'Geoproximity routing routes based on geographic proximity (with optional bias) — not measured latency.', D: 'Equal weighted routing distributes evenly regardless of latency.' } },
  { id: 'd2-r53-016', domain: 2, topics: ['CloudFront', 'signed URLs', 'signed cookies'], type: 'single', stem: 'A video streaming service needs to restrict access to premium content in CloudFront. Users must be authenticated before accessing any video file. What CloudFront feature enables this?', options: [{ id: 'A', text: 'CloudFront geo restriction' }, { id: 'B', text: 'CloudFront signed URLs or signed cookies — authenticate users before granting access to objects' }, { id: 'C', text: 'S3 bucket policy restriction' }, { id: 'D', text: 'Lambda@Edge basic auth' }], correct: ['B'], explanation: 'CloudFront signed URLs control access to individual files. Signed cookies control access to multiple files (entire directory). Both use RSA key pairs to create time-limited, user-specific access tokens.', distractors: { A: 'Geo restriction blocks entire countries — not user-level authentication.', C: 'S3 bucket policies can restrict access but authenticated distribution is CloudFront\'s job.', D: 'Lambda@Edge basic auth is a custom solution — CloudFront signed URLs/cookies are the native mechanism.' } },
  { id: 'd2-r53-017', domain: 2, topics: ['Route 53', 'multivalue answer'], type: 'single', stem: 'A company runs 6 web servers and wants Route 53 to return up to 8 healthy IP addresses per query for simple client-side load balancing (not using a load balancer). Which routing policy is appropriate?', options: [{ id: 'A', text: 'Weighted routing with equal weights' }, { id: 'B', text: 'Multivalue answer routing — returns up to 8 random healthy records per DNS query' }, { id: 'C', text: 'Latency routing' }, { id: 'D', text: 'Simple routing with multiple values' }], correct: ['B'], explanation: 'Multivalue answer routing returns up to 8 healthy IP addresses per query (randomly selected from the healthy records). Clients receive multiple IPs and can try another if one fails. It\'s not a replacement for a load balancer but provides basic redundancy.', distractors: { A: 'Weighted routing returns one record at a time based on weights — not multiple IPs.', C: 'Latency routing returns the single lowest-latency endpoint.', D: 'Simple routing with multiple values returns all IPs (including unhealthy ones) — multivalue checks health before returning IPs.' } },
  { id: 'd2-r53-018', domain: 2, topics: ['CloudFront', 'custom error pages'], type: 'single', stem: 'When an S3 origin returns a 403 error, CloudFront should display a custom maintenance page instead of the raw S3 error. How is this configured?', options: [{ id: 'A', text: 'Modify the S3 error document' }, { id: 'B', text: 'Configure CloudFront custom error responses — map S3 error codes to a custom error page cached at the edge' }, { id: 'C', text: 'Use Lambda@Edge to intercept 403 responses' }, { id: 'D', text: 'Create a separate S3 bucket for error pages' }], correct: ['B'], explanation: 'CloudFront custom error responses allow mapping origin HTTP error codes (403, 404, 500, etc.) to custom HTML error pages stored in the distribution. The custom page is served instead of the origin error response.', distractors: { A: 'S3 error documents handle static website hosting errors but don\'t apply to private S3 origins with OAC.', C: 'Lambda@Edge works but is more complex — CloudFront has native custom error response support.', D: 'A separate S3 bucket for errors would require additional Lambda/routing logic.' } },
  { id: 'd2-r53-019', domain: 2, topics: ['Route 53', 'geoproximity', 'traffic flow'], type: 'single', stem: 'A global company wants to route users in specific regions more aggressively toward their us-east-1 datacenter by adjusting the "bias" of geographic routing. Which Route 53 feature supports bias adjustment?', options: [{ id: 'A', text: 'Geolocation routing' }, { id: 'B', text: 'Geoproximity routing with bias — shrink or expand the geographic area served by an endpoint' }, { id: 'C', text: 'Weighted routing' }, { id: 'D', text: 'IP-based routing' }], correct: ['B'], explanation: 'Route 53 geoproximity routing routes based on geographic proximity. A positive bias expands the area served by that endpoint; negative bias shrinks it. Requires Route 53 Traffic Flow.', distractors: { A: 'Geolocation routes by exact country/continent — no bias adjustment.', C: 'Weighted routing divides traffic proportionally — not geographically with bias.', D: 'IP-based routing maps CIDR blocks to records — no bias concept.' } },
  { id: 'd2-r53-020', domain: 2, topics: ['CloudFront', 'field-level encryption'], type: 'single', stem: 'A CloudFront distribution processes credit card numbers. The card numbers must be encrypted at the CloudFront edge and remain encrypted through the entire processing pipeline to the application server. What feature provides this?', options: [{ id: 'A', text: 'CloudFront HTTPS (TLS termination)' }, { id: 'B', text: 'CloudFront field-level encryption — encrypts specific POST fields at the edge using a public key' }, { id: 'C', text: 'AWS KMS encryption at the origin' }, { id: 'D', text: 'S3 SSE for storing credit card data' }], correct: ['B'], explanation: 'CloudFront field-level encryption encrypts specific POST form fields (like credit card numbers) at the CloudFront edge using a public key. Only the application server with the corresponding private key can decrypt the field — intermediate services can\'t read it.', distractors: { A: 'TLS terminates at CloudFront — data is decrypted at the edge and re-encrypted in transit to origin. Field-level encryption provides additional protection within the payload.', C: 'KMS encryption at origin protects stored data but not the transmission path.', D: 'S3 SSE is for at-rest storage encryption — not request processing.' } },
  { id: 'd2-r53-021', domain: 2, topics: ['Route 53', 'TTL', 'migration'], type: 'single', stem: 'A company is planning a DNS migration from an old IP to a new IP. What should they do first, days before the migration, to enable rapid rollback if needed?', options: [{ id: 'A', text: 'Increase the TTL to reduce DNS query frequency' }, { id: 'B', text: 'Lower the TTL to a short value (e.g., 60 seconds) before migration — DNS changes propagate faster' }, { id: 'C', text: 'Delete the old DNS record immediately' }, { id: 'D', text: 'Use Route 53 weighted routing with 50/50 split' }], correct: ['B'], explanation: 'Before a DNS migration, lower TTL days in advance (e.g., from 86400 to 60). After the change propagates, fewer clients have cached the old value, so when you update the DNS record during migration, clients pick up the new value within 60 seconds instead of 24 hours.', distractors: { A: 'Increasing TTL means clients cache the old value longer — harder to migrate and roll back.', C: 'Deleting without reducing TTL first means some clients lose resolution for up to the old TTL period.', D: 'Weighted routing is useful but TTL reduction is the prerequisite preparation step.' } },
  { id: 'd2-r53-022', domain: 2, topics: ['CloudFront', 'origin groups', 'failover'], type: 'single', stem: 'A CloudFront distribution has a primary S3 origin and a backup S3 origin in another region. If the primary S3 origin returns a 5xx error, CloudFront should automatically retry the backup origin. How is this configured?', options: [{ id: 'A', text: 'Create two separate CloudFront distributions' }, { id: 'B', text: 'Configure an origin group with primary and secondary origins and specify failover criteria (e.g., HTTP 500-599)' }, { id: 'C', text: 'Use Lambda@Edge to implement failover logic' }, { id: 'D', text: 'Enable CloudFront standard logging to detect errors' }], correct: ['B'], explanation: 'CloudFront origin groups support automatic failover. Define primary and secondary origins in a group. Specify which HTTP status codes trigger failover (e.g., 503). On those errors, CloudFront automatically retries the secondary.', distractors: { A: 'Two separate distributions require external DNS-level failover — not automatic within CloudFront.', C: 'Lambda@Edge works but origin groups provide native failover without custom code.', D: 'Standard logging records events after the fact — not a failover mechanism.' } },
  { id: 'd2-r53-023', domain: 2, topics: ['Route 53', 'health check', 'CloudWatch'], type: 'single', stem: 'A Route 53 health check should monitor an application that runs only in a private subnet (no internet-facing endpoint). How can Route 53 health check a private resource?', options: [{ id: 'A', text: 'Route 53 can directly check private resources with a VPC endpoint' }, { id: 'B', text: 'Create a CloudWatch alarm monitoring the application, then create a Route 53 health check based on the CloudWatch alarm state' }, { id: 'C', text: 'Use a public IP and security groups to restrict access' }, { id: 'D', text: 'Route 53 cannot health check private resources' }], correct: ['B'], explanation: 'Route 53 health checkers run on the public internet and can\'t reach private resources. Use CloudWatch to monitor internal metrics → create a CloudWatch alarm → configure Route 53 to monitor the CloudWatch alarm state.', distractors: { A: 'Route 53 health checkers don\'t use VPC endpoints — they\'re internet-based checkers.', C: 'Making private resources accessible to Route 53 health checkers defeats the purpose of private subnets.', D: 'Health checking private resources is possible via the CloudWatch alarm method.' } },
  { id: 'd2-r53-024', domain: 2, topics: ['CloudFront', 'caching', 'query strings'], type: 'single', stem: 'A CloudFront distribution caches API responses. The API uses query strings like ?lang=en and ?lang=fr to serve different content. CloudFront is serving the same content regardless of language. What is the problem?', options: [{ id: 'A', text: 'CloudFront doesn\'t support query strings' }, { id: 'B', text: 'By default CloudFront ignores query strings — configure the cache policy to include the lang parameter in the cache key' }, { id: 'C', text: 'The API is not sending different responses per language' }, { id: 'D', text: 'Enable HTTPS to fix query string handling' }], correct: ['B'], explanation: 'CloudFront by default ignores query strings and caches based only on the path. To cache different content per query string value, configure the cache policy to include specific query strings (like "lang") in the cache key.', distractors: { A: 'CloudFront does support query strings — it ignores them by default unless configured otherwise.', C: 'The problem description indicates the API does serve different content per language — the caching configuration is the issue.', D: 'HTTPS is unrelated to cache key configuration.' } },
  { id: 'd2-r53-025', domain: 2, topics: ['Route 53', 'domain registration', 'transfer'], type: 'single', stem: 'A company purchased a domain through a third-party registrar and wants to use Route 53 for DNS. They do NOT want to transfer the domain registration. What should they do?', options: [{ id: 'A', text: 'Transfer the domain to Route 53 registrar' }, { id: 'B', text: 'Create a Route 53 hosted zone and update the domain nameservers at the registrar to point to Route 53\'s name servers' }, { id: 'C', text: 'Route 53 can only manage domains registered through Route 53' }, { id: 'D', text: 'Use Route 53 Resolver instead' }], correct: ['B'], explanation: 'Route 53 hosted zones work independently of domain registration. Create a public hosted zone in Route 53, then update the nameserver (NS) records at the third-party registrar to Route 53\'s four nameservers.', distractors: { A: 'Transfer is optional — you can keep the registrar and still use Route 53 for DNS.', C: 'Route 53 DNS management works for any domain — registration and DNS are separate concerns.', D: 'Route 53 Resolver is for hybrid DNS (VPC to on-premises) — not for managing public DNS.' } },
  { id: 'd2-r53-026', domain: 2, topics: ['CloudFront', 'real-time logs'], type: 'single', stem: 'A data team wants to analyze CloudFront request logs in near real-time (within seconds) for anomaly detection. Standard logging has multi-minute delays. What CloudFront feature supports near real-time log delivery?', options: [{ id: 'A', text: 'CloudFront standard logging to S3' }, { id: 'B', text: 'CloudFront real-time logs delivered to Kinesis Data Streams — sub-second latency' }, { id: 'C', text: 'CloudWatch Logs for CloudFront' }, { id: 'D', text: 'CloudTrail for CloudFront API calls' }], correct: ['B'], explanation: 'CloudFront real-time logs deliver log records to a Kinesis Data Stream within 1 second of the request. This enables real-time analytics, anomaly detection, and monitoring pipelines.', distractors: { A: 'Standard logging writes to S3 with multi-minute delays — not near real-time.', C: 'CloudFront doesn\'t write access logs to CloudWatch Logs natively — CloudWatch captures CloudFront metrics, not access logs.', D: 'CloudTrail captures CloudFront API calls (configuration changes) — not request access logs.' } },
  { id: 'd2-r53-027', domain: 2, topics: ['Route 53', 'traffic flow', 'complex routing'], type: 'single', stem: 'A company needs a Route 53 routing policy combining latency-based routing with failover to a backup region. They want to visually create and manage complex routing logic. What feature helps?', options: [{ id: 'A', text: 'Create individual routing policy records manually' }, { id: 'B', text: 'Route 53 Traffic Flow — visual editor for creating complex nested routing policies as a traffic policy' }, { id: 'C', text: 'Route 53 Resolver' }, { id: 'D', text: 'CloudFront routing rules' }], correct: ['B'], explanation: 'Route 53 Traffic Flow provides a visual interface for creating complex routing configurations that combine multiple routing types (latency + failover + weighted + geolocation). Policies can be versioned and applied to multiple records.', distractors: { A: 'Manual records can\'t easily combine multiple routing types — Traffic Flow is designed for this.', C: 'Route 53 Resolver handles hybrid DNS resolution — not complex routing policy creation.', D: 'CloudFront routing is about cache behaviors and origins — not Route 53 DNS routing.' } },
  { id: 'd2-r53-028', domain: 2, topics: ['CloudFront', 'invalidation', 'cache'], type: 'single', stem: 'A development team deployed a new version of their JavaScript application to S3. CloudFront is still serving the old cached version. How should the cache be refreshed?', options: [{ id: 'A', text: 'Wait for the TTL to expire' }, { id: 'B', text: 'Create a CloudFront invalidation for the updated paths (e.g., /app.js or /*) to remove cached copies' }, { id: 'C', text: 'Delete and recreate the CloudFront distribution' }, { id: 'D', text: 'Change the S3 bucket name' }], correct: ['B'], explanation: 'CloudFront invalidations remove specific cached objects from edge locations before the TTL expires. Use specific paths (/app.js) or wildcards (/*) to invalidate. First 1,000 invalidation paths per month are free; additional paths are charged.', distractors: { A: 'Waiting for TTL works but may take hours — invalidation provides immediate refresh.', C: 'Recreating the distribution loses all configuration and takes time — invalidation is the right approach.', D: 'Changing the S3 bucket name would break the entire distribution.' } },
  { id: 'd2-r53-029', domain: 2, topics: ['Route 53', 'CNAME vs A record'], type: 'single', stem: 'A company\'s application endpoint changes IP addresses frequently. What DNS record type should be used to avoid IP address updates?', options: [{ id: 'A', text: 'A record — requires manual IP updates' }, { id: 'B', text: 'CNAME record pointing to a stable hostname — the hostname resolves to the current IP' }, { id: 'C', text: 'MX record' }, { id: 'D', text: 'SRV record' }], correct: ['B'], explanation: 'A CNAME record (alias) points to a hostname rather than an IP address. When the underlying service changes IPs, only the target hostname\'s A record needs updating — all CNAMEs pointing to it automatically resolve to the new IP.', distractors: { A: 'A records require manual updates when IPs change — CNAME is more flexible.', C: 'MX records are for mail exchange — not web application DNS.', D: 'SRV records specify service location (host and port) — typically for VoIP or game servers, not general web apps.' } },
  { id: 'd2-r53-030', domain: 2, topics: ['CloudFront', 'cache hit ratio', 'optimization'], type: 'single', stem: 'A CloudFront distribution has a low cache hit ratio (20%). Most requests are going to the origin. What could improve the cache hit ratio?', options: [{ id: 'A', text: 'Increase the number of edge locations' }, { id: 'B', text: 'Remove unnecessary headers, cookies, and query strings from the cache key — reduce cache key variability' }, { id: 'C', text: 'Decrease the TTL' }, { id: 'D', text: 'Switch to a different CloudFront price class' }], correct: ['B'], explanation: 'A low hit ratio often means the cache key is too specific. If CloudFront includes all headers/cookies/query strings, every slightly different request misses cache. Reducing cache key components (only include what matters for content differentiation) improves hit ratio.', distractors: { A: 'More edge locations distribute hits — they don\'t change the hit ratio.', C: 'Lower TTL means objects expire faster — further reducing the hit ratio.', D: 'Price class affects which regions are used — not cache hit ratio.' } },
  { id: 'd2-r53-031', domain: 2, topics: ['Route 53', 'split-view DNS'], type: 'single', stem: 'An application should resolve to different IP addresses for internal corporate users vs. external internet users — using the same domain name. How is this achieved with Route 53?', options: [{ id: 'A', text: 'Create two separate domain names' }, { id: 'B', text: 'Split-view (split-horizon) DNS — create a public hosted zone with external IPs and a private hosted zone (same domain) with internal IPs' }, { id: 'C', text: 'Use Route 53 weighted routing' }, { id: 'D', text: 'Configure DHCP options for internal users' }], correct: ['B'], explanation: 'Split-horizon DNS: create both a public hosted zone and a private hosted zone for the same domain name. Internal VPC users (with private zone association) resolve to internal IPs; external users resolve through the public zone to external IPs.', distractors: { A: 'Different domain names defeat the purpose — split-view uses the same name for different populations.', C: 'Weighted routing doesn\'t differentiate between internal and external users.', D: 'DHCP options point to a DNS server — still needs the split-view configuration.' } },
  { id: 'd2-r53-032', domain: 2, topics: ['CloudFront', 'CloudFront Functions', 'viewer request'], type: 'single', stem: 'A team needs to run lightweight URL rewriting (add a header to every request) at CloudFront edges with sub-millisecond latency and very low cost. What is the best option?', options: [{ id: 'A', text: 'Lambda@Edge' }, { id: 'B', text: 'CloudFront Functions — JavaScript functions with microsecond execution time, cheaper than Lambda@Edge' }, { id: 'C', text: 'API Gateway' }, { id: 'D', text: 'Application Load Balancer rules' }], correct: ['B'], explanation: 'CloudFront Functions run JavaScript in microseconds (vs. Lambda@Edge milliseconds) and are ~6x cheaper. They run only at viewer request/response events for lightweight logic: URL rewrites, header manipulation, A/B testing.', distractors: { A: 'Lambda@Edge supports full Node.js/Python but with millisecond startup and higher cost — overkill for simple rewrites.', C: 'API Gateway is an origin, not edge logic.', D: 'ALB rules process traffic at the origin region, not at CloudFront edges.' } },
  { id: 'd2-r53-033', domain: 2, topics: ['Route 53', 'registrar', 'domain lock'], type: 'single', stem: 'A domain registered with Route 53 Registrar is being transferred away by an unauthorized person. What protects against unauthorized domain transfers?', options: [{ id: 'A', text: 'Route 53 public hosted zone protection' }, { id: 'B', text: 'Domain transfer lock (Registrar Lock) — prevents domain transfers until the lock is removed by the account owner' }, { id: 'C', text: 'Route 53 DNSSEC' }, { id: 'D', text: 'AWS Shield' }], correct: ['B'], explanation: 'The Registrar Lock (transfer lock) prevents domain transfers. The domain owner must unlock it before a transfer can proceed. Route 53 domains have transfer lock enabled by default.', distractors: { A: 'Hosted zone protection (deletion protection) doesn\'t prevent domain transfers.', C: 'DNSSEC prevents DNS spoofing — not domain registrar transfers.', D: 'AWS Shield protects against DDoS — not unauthorized domain transfers.' } },
  { id: 'd2-r53-034', domain: 2, topics: ['CloudFront', 'WebSocket', 'long-lived connections'], type: 'single', stem: 'A real-time chat application needs WebSocket connections. The frontend uses CloudFront. Does CloudFront support WebSocket?', options: [{ id: 'A', text: 'No — WebSocket requires a direct connection to the origin, not via CloudFront' }, { id: 'B', text: 'Yes — CloudFront supports WebSocket protocol natively, no special configuration needed' }, { id: 'C', text: 'Only with Lambda@Edge' }, { id: 'D', text: 'Only with HTTP/2' }], correct: ['B'], explanation: 'CloudFront natively supports WebSocket protocol. WebSocket upgrade requests are transparently proxied through CloudFront to the origin. No special configuration is required.', distractors: { A: 'WebSocket works through CloudFront without any special configuration.', C: 'Lambda@Edge is not required for WebSocket support.', D: 'WebSocket works with both HTTP/1.1 and HTTP/2 through CloudFront.' } },
  { id: 'd2-r53-035', domain: 2, topics: ['Route 53', 'IP-based routing'], type: 'single', stem: 'A company wants to route traffic from specific corporate office IP ranges to a dedicated backend, and all other traffic to a general backend. Which Route 53 routing policy enables this?', options: [{ id: 'A', text: 'Geolocation routing (by country)' }, { id: 'B', text: 'IP-based routing — maps CIDR blocks to specific record values' }, { id: 'C', text: 'Weighted routing' }, { id: 'D', text: 'Geoproximity routing' }], correct: ['B'], explanation: 'Route 53 IP-based routing (GA since 2023) maps client IP CIDR blocks to specific endpoints. Create CIDR collections and associate them with routing records. Corporate office CIDRs route to the dedicated backend; all others get the default.', distractors: { A: 'Geolocation routes by country/continent — not by specific IP ranges.', C: 'Weighted routing distributes proportionally — not by IP range.', D: 'Geoproximity routes by geographic distance — not by specific IP ranges.' } },
  { id: 'd2-r53-036', domain: 2, topics: ['CloudFront', 'Continuous Deployment'], type: 'single', stem: 'A team wants to test a new CloudFront configuration on 5% of production traffic before fully deploying it. What feature supports this?', options: [{ id: 'A', text: 'CloudFront weighted routing' }, { id: 'B', text: 'CloudFront Continuous Deployment — create a staging distribution and use traffic split to route a percentage of traffic to it' }, { id: 'C', text: 'Route 53 weighted routing to different CloudFront distributions' }, { id: 'D', text: 'CloudFront A/B testing with Lambda@Edge' }], correct: ['B'], explanation: 'CloudFront Continuous Deployment allows creating a staging distribution with a new configuration and splitting a percentage of production traffic to it. After validation, promote the staging config to production with one click.', distractors: { A: 'CloudFront doesn\'t have a "weighted routing" feature — Route 53 has weighted routing.', C: 'Route 53 weighted routing works but is not CloudFront-native — Continuous Deployment is built into CloudFront.', D: 'Lambda@Edge can implement A/B testing but Continuous Deployment is simpler for configuration testing.' } },
  { id: 'd2-r53-037', domain: 2, topics: ['Route 53', 'SOA record', 'NS record'], type: 'single', stem: 'When a new public hosted zone is created in Route 53, which records are automatically created?', options: [{ id: 'A', text: 'A record and CNAME record' }, { id: 'B', text: 'NS (Name Server) record and SOA (Start of Authority) record' }, { id: 'C', text: 'MX record and TXT record' }, { id: 'D', text: 'AAAA record and CAA record' }], correct: ['B'], explanation: 'Route 53 automatically creates NS and SOA records for every new public hosted zone. The NS records list the four Route 53 nameservers for the zone. The SOA record contains administrative information about the zone.', distractors: { A: 'A and CNAME records must be created manually for the domain\'s resources.', C: 'MX and TXT records are created manually for email and verification purposes.', D: 'AAAA and CAA records require manual creation.' } },
  { id: 'd2-r53-038', domain: 2, topics: ['CloudFront', 'access logs', 'S3'], type: 'single', stem: 'A security team needs to audit all CloudFront requests including client IPs, user agents, and response codes for compliance purposes. What feature provides this?', options: [{ id: 'A', text: 'CloudWatch metrics' }, { id: 'B', text: 'CloudFront standard access logs — delivers compressed log files to an S3 bucket' }, { id: 'C', text: 'VPC Flow Logs' }, { id: 'D', text: 'AWS Config' }], correct: ['B'], explanation: 'CloudFront standard access logs record every request to the distribution, including client IP, user agent, request URI, response code, bytes transferred, and more. Logs are delivered to a specified S3 bucket in gzip format.', distractors: { A: 'CloudWatch metrics provide aggregate statistics (total requests, error rate, latency) — not per-request detail.', C: 'VPC Flow Logs capture network traffic within VPCs — CloudFront is a global edge network outside VPCs.', D: 'AWS Config tracks configuration state changes — not request logs.' } },
  { id: 'd2-r53-039', domain: 2, topics: ['Route 53', 'resolver endpoints', 'inbound'], type: 'single', stem: 'On-premises servers need to resolve AWS private DNS names (e.g., RDS endpoint hostnames in a private hosted zone). What Route 53 component enables on-premises to resolve Route 53 private zones?', options: [{ id: 'A', text: 'Route 53 Resolver outbound endpoint' }, { id: 'B', text: 'Route 53 Resolver inbound endpoint — on-premises DNS servers forward AWS queries to the inbound endpoint IP' }, { id: 'C', text: 'Route 53 public hosted zone' }, { id: 'D', text: 'Direct Connect BGP routing' }], correct: ['B'], explanation: 'Route 53 Resolver inbound endpoints provide IP addresses in your VPC that on-premises DNS servers can forward queries to. On-premises machines query their local DNS → forwarding rule sends AWS domain queries to the inbound endpoint → resolves private hosted zone records.', distractors: { A: 'Outbound endpoints forward queries FROM the VPC TO on-premises — the reverse direction.', C: 'Public hosted zones are internet-facing — not for resolving private on-premises DNS queries.', D: 'Direct Connect BGP is for network routing — not DNS resolution.' } },
  { id: 'd2-r53-040', domain: 2, topics: ['CloudFront', 'HTTP to HTTPS redirect'], type: 'single', stem: 'A CloudFront distribution should redirect all HTTP requests to HTTPS. Where is this configured?', options: [{ id: 'A', text: 'Configure an HTTP→HTTPS redirect in the origin S3 bucket' }, { id: 'B', text: 'Set the viewer protocol policy to "Redirect HTTP to HTTPS" in the CloudFront distribution cache behavior' }, { id: 'C', text: 'Use Lambda@Edge to detect HTTP and return 301 redirect' }, { id: 'D', text: 'Configure ALB to redirect HTTP to HTTPS' }], correct: ['B'], explanation: 'The CloudFront viewer protocol policy setting on each cache behavior controls how HTTP/HTTPS requests are handled. "Redirect HTTP to HTTPS" returns a 301/302 redirect for HTTP requests, sending clients to the HTTPS URL.', distractors: { A: 'S3 static website hosting has redirect options but they don\'t redirect at the edge — only on direct S3 requests.', C: 'Lambda@Edge works but is overkill — native viewer protocol policy handles this.', D: 'ALB redirect rules work at the origin — CloudFront viewer protocol policy handles it at the edge.' } },
  { id: 'd2-r53-041', domain: 2, topics: ['Route 53', 'health check intervals'], type: 'single', stem: 'Route 53 health checks are not detecting failures quickly enough. What configuration reduces the time to detect an unhealthy endpoint?', options: [{ id: 'A', text: 'Increase the failure threshold' }, { id: 'B', text: 'Set the health check interval to 10 seconds (fast health check) — reduces detection time to 30 seconds' }, { id: 'C', text: 'Increase the number of health check regions' }, { id: 'D', text: 'Switch from HTTP to TCP health check' }], correct: ['B'], explanation: 'Route 53 standard health check interval is 30 seconds. Fast health checks run every 10 seconds. With a threshold of 3 consecutive failures, fast health checks detect failures in approximately 30 seconds (vs. 90+ seconds with standard checks).', distractors: { A: 'Higher failure threshold requires more failures before marking unhealthy — increases detection time.', C: 'More regions improves accuracy/resilience of the check — doesn\'t change detection speed.', D: 'TCP checks are faster per check but the interval setting (30s vs 10s) determines overall detection time.' } },
  { id: 'd2-r53-042', domain: 2, topics: ['CloudFront', 'origin shield'], type: 'single', stem: 'A CloudFront distribution has origins in multiple regions. Cache misses from edge locations worldwide are all hitting the origin directly, causing high origin load. What reduces origin load while improving cache efficiency?', options: [{ id: 'A', text: 'Increase CloudFront TTL' }, { id: 'B', text: 'Enable CloudFront Origin Shield — adds a centralized caching layer between edge locations and the origin' }, { id: 'C', text: 'Use multiple origins' }, { id: 'D', text: 'Enable origin access control' }], correct: ['B'], explanation: 'CloudFront Origin Shield is an additional caching layer in a single AWS region between all edge locations and the origin. Cache misses from edges check Origin Shield before going to the origin, reducing origin requests by up to 90%.', distractors: { A: 'Higher TTL means cached content is served longer — reduces misses but doesn\'t help with concurrent miss storms.', C: 'Multiple origins increase availability but don\'t reduce requests — they add more places to fail.', D: 'OAC controls S3 access — not origin caching.' } },
  { id: 'd2-r53-043', domain: 2, topics: ['Route 53', 'routing', 'exam trap'], type: 'single', stem: 'Route 53 latency-based routing is configured with endpoints in us-east-1 and eu-west-1. A user in London makes a request. Will they always go to eu-west-1?', options: [{ id: 'A', text: 'Yes — users always go to the geographically nearest region with latency routing' }, { id: 'B', text: 'Not necessarily — latency routing measures actual AWS latency, and sometimes us-east-1 could have lower measured latency than eu-west-1' }, { id: 'C', text: 'Route 53 uses geolocation, not latency measurements' }, { id: 'D', text: 'The user always goes to eu-west-1 because London is in Europe' }], correct: ['B'], explanation: 'Latency routing is based on empirical latency measurements, not geographic proximity. While EU users typically get better latency to eu-west-1, network conditions can vary. Route 53 uses historical latency data from multiple source points to make routing decisions.', distractors: { A: 'Geographic proximity and latency are correlated but not identical — network conditions matter.', C: 'Latency routing uses actual latency measurements — geolocation routing uses geographic location.', D: 'The geographic "London is in Europe" logic is exactly what geolocation routing does, not latency routing.' } },
  { id: 'd2-r53-044', domain: 2, topics: ['CloudFront', 'CORS'], type: 'single', stem: 'A React app hosted on CloudFront at app.example.com calls an API hosted on api.example.com. CORS preflight requests (OPTIONS) are being cached by CloudFront, causing CORS errors. How should this be fixed?', options: [{ id: 'A', text: 'Disable CloudFront caching entirely' }, { id: 'B', text: 'Configure the CloudFront cache policy to include the Origin and Access-Control-Request-* headers in the cache key — ensures CORS headers are considered for caching' }, { id: 'C', text: 'Move the API to the same domain as the React app' }, { id: 'D', text: 'Use HTTP instead of HTTPS' }], correct: ['B'], explanation: 'CloudFront must include the Origin header (and Access-Control-Request-Headers, Access-Control-Request-Method) in the cache key for CORS to work correctly. Without these, CloudFront may return a cached response without the CORS headers that the OPTIONS request needs.', distractors: { A: 'Disabling caching eliminates the benefit of CloudFront — the correct fix is to include CORS headers in the cache key.', C: 'Same-domain hosting eliminates CORS but requires architecture changes — cache key configuration is the targeted fix.', D: 'HTTPS vs. HTTP doesn\'t affect CORS header caching behavior.' } },
  { id: 'd2-r53-045', domain: 2, topics: ['Route 53', 'domains', 'TLD'], type: 'single', stem: 'A company registered example.co.uk with Route 53 Registrar. Which other AWS service is automatically created during domain registration?', options: [{ id: 'A', text: 'A CloudFront distribution' }, { id: 'B', text: 'A Route 53 public hosted zone — created automatically to manage the domain\'s DNS records' }, { id: 'C', text: 'An ACM certificate' }, { id: 'D', text: 'An S3 bucket with the domain name' }], correct: ['B'], explanation: 'When a domain is registered through Route 53 Registrar, a public hosted zone is automatically created for the domain. NS records in the hosted zone are configured as the domain\'s nameservers automatically.', distractors: { A: 'A CloudFront distribution must be created manually — not automatic with domain registration.', C: 'ACM certificate issuance requires explicit request — not automatic.', D: 'S3 buckets are not automatically created with domain registration.' } },
]
